{{(() => {
  const ratings = [
    Rating47.value,
    Rating48.value,
    Rating49.value,
    Rating50.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "blue";
  }

  const somma = ratings.reduce((acc, val) => acc + val, 0);

  return somma === 0 ? "" : (somma >= 8 ? "green" : "red");
